vec3 palette( float t ){
     vec3 a = vec3(.5,.5,.5);
     vec3 b = vec3(.5,.5,.5);
     vec3 c = vec3(1.,1.,.1);
     vec3 d = vec3(sin(iTime*0.345),cos(iTime*1.864),sin(iTime+1.));
     return a+b*cos( 6.28318*(c*t+d) );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy*2.-1.;

    uv.x*=iResolution.x/iResolution.y;

    vec3 fcol=vec3(0.);

    vec2 uv0=uv;

    uv.x+=sin(uv.y*8.+iTime)/8.;

    uv.y+=cos(uv.x*8.+iTime)/8.;

    uv.y/=pow(.01/abs(uv.x),uv.y*0.2);

    uv.x*=pow(.01/abs(uv.y),uv.x*0.2);

    uv.x+=sin(uv.y*8.+iTime)/8.;

    uv.y+=cos(uv.x*8.+iTime)/8.;

    uv.x-=length(uv);

    uv.y+=length(uv);

    float d=length(uv)*exp(-length(uv0));

    d=sin(d*uv.x+iTime)/uv.y;

    d=abs(d);

    d=pow(0.01/d,1.2);

    d=sin(d*16.+iTime)/16.;

    d=abs(d);

    d=pow(0.01/d,1.2);

    vec3 col = tan(palette(length(uv) + iTime*0.4));

    fcol=d*col;

    fragColor = vec4(fcol,1.0);
}
